<template><div class="work-page"><div class="mobile-nav-extra"><RouterLink to="/review">核对工作台</RouterLink><RouterLink to="/plans">账单与还款</RouterLink><RouterLink to="/accounts">账户</RouterLink><RouterLink to="/settings/import-bills">导入</RouterLink><RouterLink to="/insights">订阅与预算</RouterLink></div><header class="page-heading"><div><p class="eyebrow">{{eyebrow}}</p><h1>{{title}}</h1><p class="subtitle">{{subtitle}}</p></div><div class="actions workspace-heading-actions"><RouterLink v-if="mode==='ledger'||mode==='home'" to="/record" class="button primary workspace-record-action">＋ 记一笔</RouterLink><RouterLink v-if="mode==='ledger'" to="/timeline" class="button">日历视图</RouterLink><select v-model="filters.currency" class="control workspace-currency" aria-label="统计币种" @change="refresh"><option value="CNY">CNY · 人民币</option><option value="USD">USD · 美元</option></select></div></header>
<div v-if="error" class="error-box" role="alert">{{error}} <button @click="load">重试</button></div>
<div v-if="mode==='review'" class="queue-grid"><button v-for="q in queues" :key="q.key" class="queue-card" :class="{active:filters.queue===q.key}" @click="selectQueue(q.key)"><span>{{q.name}}</span><strong>{{data?.queues[q.key]||0}}</strong></button></div>
<div v-if="mode==='home'" class="notice">当前展示已收集账单的消费分析。账户余额尚需独立核验，历史消费累计不代表当前欠款。<RouterLink to="/accounts">核验账户 →</RouterLink></div>
<div v-if="mode==='reports'" class="actions" style="margin-bottom:16px"><div class="tabs" style="padding:0"><button :class="{active:period==='year'}" @click="period='year';setPeriod()">年度分析</button><button :class="{active:period==='month'}" @click="period='month';setPeriod()">月度分析</button></div><select v-if="period==='year'" v-model="year" class="control" aria-label="分析年份" @change="setPeriod"><option v-for="y in years" :key="y">{{y}}</option></select><input v-else v-model="month" type="month" class="control" aria-label="分析月份" @change="setPeriod"/><span class="subtle tiny">退款计入实际发生期间</span></div>
<div class="panel"><div v-if="mode==='plans'" class="tabs"><button v-for="t in planTabs" :key="t.key" :class="{active:filters.kind===t.key}" @click="filters.kind=t.key;refresh()">{{t.name}}</button></div><div class="toolbar" :class="{expanded:filtersExpanded}"><input v-model="filters.q" class="control search" aria-label="搜索账本" placeholder="搜索商户、摘要、标签…" @keyup.enter="refresh"/><button class="button filter-toggle" :aria-expanded="filtersExpanded" @click="filtersExpanded=!filtersExpanded">筛选{{activeFilterCount?' · '+activeFilterCount:''}}</button><input v-if="mode!=='reports'" v-model="filters.from" type="date" class="control" aria-label="开始日期" @change="refresh"/><span v-if="mode!=='reports'" class="subtle tiny">至</span><input v-if="mode!=='reports'" v-model="filters.to" type="date" class="control" aria-label="结束日期" @change="refresh"/><select v-model="filters.bank" class="control" aria-label="银行" @change="refresh"><option value="">全部银行</option><option value="cmb">招商银行</option><option value="ceb">光大银行</option></select><select v-model="filters.account" class="control" aria-label="账户" @change="refresh"><option value="">全部账户</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{accountName(a)}}</option></select><select v-if="mode!=='plans'" v-model="filters.confirmation" class="control" aria-label="账单确认状态" @change="refresh"><option value="">全部确认状态</option><option value="formal">正式账单</option><option value="pending">摘要待确认</option><option value="manual">手工记录</option></select><select v-if="mode==='ledger'" v-model="filters.kind" class="control" aria-label="交易类型" @change="refresh"><option value="ledger">全部交易</option><option value="expense">消费</option><option value="refund">退款</option><option value="income">收入</option><option value="transfer">转账</option></select><select v-if="mode==='ledger'||mode==='reports'" v-model="filters.category" class="control" aria-label="消费分类" @change="refresh"><option value="">全部分类</option><option v-for="cat in data?.categories" :key="cat.id" :value="cat.id">{{cat.name}}</option></select><button class="button" @click="refresh">查询</button><button class="button ghost" @click="reset">重置</button></div></div>
<p class="scope-note">{{filters.currency}} · {{filters.bank?bankName(filters.bank):'全部银行'}} · {{filters.from||'最早记录'}} — {{filters.to||'最新记录'}} · {{filters.confirmation?stateNames[filters.confirmation]:'含正式记录与摘要待确认'}}<span v-if="data?.analysis.first">；所选记录覆盖 {{data.analysis.first}} 至 {{data.analysis.last}}</span></p>
<div v-if="loading&&!data" class="empty">正在加载工作台…</div><template v-if="data"><div v-if="mode!=='plans'&&mode!=='review'" class="metrics"><div class="metric"><p class="metric-label"><i class="dot"/>消费总额</p><div class="metric-value">{{money(data.analysis.gross)}}</div><p class="metric-foot">{{data.analysis.count.toLocaleString()}} 笔消费 · 不含还款与凭证</p></div><div class="metric"><p class="metric-label"><i class="dot" style="background:#8abdac"/>退款总额</p><div class="metric-value refund">{{money(data.analysis.refund)}}</div><p class="metric-foot">{{data.analysis.refundCount}} 笔退款 · 冲减支出</p></div><div class="metric accent"><p class="metric-label">净支出</p><div class="metric-value">{{money(data.analysis.net)}}</div><p class="metric-foot">消费总额 − 退款总额</p></div><div class="metric"><p class="metric-label">平均单笔消费</p><div class="metric-value">{{money(data.analysis.average)}}</div><p class="metric-foot">仅按消费记录计算</p></div></div>
<div v-if="mode==='home'" class="queue-grid"><RouterLink v-for="q in queues" :key="q.key" :to="{path:'/review',query:{queue:q.key}}" class="queue-card"><span>{{q.name}}</span><strong>{{data.queues[q.key]||0}}</strong></RouterLink></div>
<template v-if="mode==='home'||mode==='reports'"><div class="split-grid"><section class="panel"><div class="panel-head"><h2>{{period==='year'&&mode==='reports'?'年度消费与退款':'消费与退款趋势'}}</h2><span class="tiny subtle">{{filters.currency}}</span></div><AnalysisChart :items="data.analysis.trend" type="trend" :show="show" label="消费与退款趋势，点击柱形查看明细" @select="openPeriod"/></section><section class="panel"><div class="panel-head"><h2>分类分布</h2><select v-model="categoryMetric" class="control" aria-label="分类统计口径"><option value="gross">消费总额</option><option value="net">净支出</option></select></div><AnalysisChart :items="data.analysis.categories" type="category" :metric="categoryMetric" :show="show" label="分类支出条形图" @select="openCategory"/></section></div><div v-if="mode==='reports'" class="two-grid" style="margin-bottom:20px"><section class="panel"><div class="panel-head"><h2>商户 Top 15</h2><span class="tiny subtle">按消费总额</span></div><div class="panel-body"><button v-for="(g,i) in data.analysis.merchants" :key="g.key" class="insight-row" style="width:100%;background:white;text-align:left" @click="router.push({path:'/detail',query:{...linkFilters,q:g.key}})"><span><span class="subtle tiny" style="margin-right:12px">{{String(i+1).padStart(2,'0')}}</span>{{g.name||'未填写商户'}}</span><span>{{money(g.gross)}}</span></button><p v-if="!data.analysis.merchants.length" class="empty">暂无消费记录</p></div></section><section class="panel"><div class="panel-head"><h2>支付渠道与资料覆盖</h2></div><div class="panel-body"><button v-for="g in data.analysis.channels" :key="g.key" class="insight-row" style="width:100%;background:white" @click="router.push({path:'/detail',query:{...linkFilters,channel:g.key}})"><span>{{g.name}}</span><span>{{money(g.gross)}}</span></button><div class="notice">已记录 {{data.analysis.months.length}} 个月。没有记录的月份可能是资料未覆盖，不代表没有消费；不完整年份不直接作全年同比。</div><div v-if="period==='year'" class="coverage"><span v-for="m in 12" :key="m" :title="m+'月'" :class="{filled:data.analysis.months.includes(year+'-'+String(m).padStart(2,'0'))}"/></div><div class="notice">全历史同币种资料质量：凭证关联 {{data.quality.matchedReceipts}} / {{data.quality.receipts}}；退款人工确认 {{data.quality.confirmedRefunds}} / {{data.quality.refunds}}。<br/>待分类 {{data.quality.unclassified}}，平台待细分 {{data.quality.platform}}。<br/>参考明细中的手续费 / 利息 {{money(data.quality.feeCents)}}（{{data.quality.feeRecords}} 条，单列、不计入消费总额）。</div><p class="subtitle">退款率：{{data.analysis.gross>0?(data.analysis.refund/data.analysis.gross*100).toFixed(1)+'%':'—'}} · 摘要待确认消费 {{money(data.analysis.pending)}}</p></div></section></div></template>
<section v-if="mode!=='reports'" class="panel" :aria-busy="loading"><div class="panel-head"><div><h2>{{mode==='home'?'最近交易':mode==='review'?'待核对记录':mode==='plans'?'账单与计划':'交易记录'}}</h2><p class="subtitle">共 {{data.total.toLocaleString()}} 条{{loading?' · 更新中…':''}}</p></div><RouterLink v-if="mode==='home'" to="/detail" class="button ghost">全部账本 →</RouterLink><div v-if="selected.length" class="actions"><span class="tiny">本页已选 {{selected.length}} 条</span><select v-model="bulkCategory" class="control" aria-label="批量分类"><option value="">选择分类</option><option v-for="c in data.categories" :key="c.id" :value="c.id">{{c.name}}</option></select><button class="button primary" :disabled="!bulkCategory||saving" @click="bulkSave">应用分类</button></div></div><LedgerTable :items="mode==='home'?data.items.slice(0,6):data.items" :currency="filters.currency" :show="show" :selectable="mode==='ledger'||mode==='review'" :selected="selected" @select="selected=$event" @open="recordKey=$event"/><footer v-if="mode!=='home'" class="pagination"><span>{{data.total?data.offset+1:0}}–{{Math.min(data.offset+data.items.length,data.total)}} / {{data.total}}</span><div class="actions"><button class="button" :disabled="!offset||loading" @click="offset-=50;load()">上一页</button><button class="button" :disabled="!data.hasMore||loading" @click="offset+=50;load()">下一页</button></div></footer></section><section v-if="mode==='plans'&&projection" class="panel" style="margin-top:20px"><div class="panel-head"><h2>未来 90 天还款现金流</h2><span class="tag">{{filters.currency}}</span></div><div class="panel-body"><p class="subtitle">仅扣减有效的已出账 / 预计还款，不含未来收入与日常消费。{{projection.starting===null?'尚无已核验现金账户，暂不推算剩余余额。':''}}{{projection.unknownAmounts?'存在金额待确认事项，暂不推算余额。':''}}</p><div class="table-scroll"><table class="ledger-table"><thead><tr><th>到期日</th><th>正式应还</th><th>预计应还</th><th>还款后现金余额</th></tr></thead><tbody><tr v-for="p in projection.points.filter(p=>p.billed||p.estimated)" :key="p.date"><td>{{p.date}}</td><td>{{money(p.billed)}}</td><td>{{money(p.estimated)}}</td><td>{{p.remaining===null?'待核实':money(p.remaining)}}</td></tr></tbody></table></div></div></section><p v-if="mode==='plans'" class="scope-note">正式账单、预计还款分别展示；计划不计入历史消费。点击记录可核实状态、查看完整应还与最低还款信息。</p></template><RecordDrawer v-if="recordKey" :record-key="recordKey" :categories="data?.categories||[]" :show="show" @close="recordKey=''" @open="recordKey=$event" @saved="load"/></div></template>
<script setup lang="ts">
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {get} from '@/api/http'
import {getWorkspace,saveEdits,amount,accountName,bankName,stateNames,localDate} from '@/api/workspace'
import type {Result} from '@/api/workspace'
import {useUserSettingsStore} from '@/stores/userSettings'
import LedgerTable from '@/components/LedgerTable.vue'
import RecordDrawer from '@/components/RecordDrawer.vue'
import AnalysisChart from '@/components/AnalysisChart.vue'
const route=useRoute(),router=useRouter(),settings=useUserSettingsStore()
const mode=computed(()=>({'/':'home','/detail':'ledger','/reports':'reports','/review':'review','/plans':'plans'}[route.path]||'ledger'))
const title=computed(()=>({home:'财务总览',ledger:'交易账本',reports:'分析报表',review:'核对工作台',plans:'账单与还款'}[mode.value]))
const eyebrow=computed(()=>({home:'OVERVIEW',ledger:'YOUR LEDGER',reports:'SPENDING INSIGHTS',review:'REVIEW CENTER',plans:'BILLS & REPAYMENTS'}[mode.value]))
const subtitle=computed(()=>({home:'了解支出的去向，把需要关注的事项放在眼前。',ledger:'每一笔消费、退款与收入，都清晰可查。',reports:'同一口径，读懂每一年、每个月的消费。',review:'逐项核实分类、退款与凭证，让记录更可靠。',plans:'区分正式账单与预计还款，保留每次核实结果。'}[mode.value]))
const filters=reactive({currency:'CNY',from:'',to:'',bank:'',account:'',category:'',kind:'ledger',confirmation:'',q:'',queue:'',channel:''})
const data=ref<Result|null>(null),loading=ref(false),error=ref(''),offset=ref(0),recordKey=ref(''),selected=ref<string[]>([]),bulkCategory=ref(''),saving=ref(false)
const year=ref(String(new Date().getFullYear())),month=ref(localDate().slice(0,7)),period=ref<'year'|'month'>('year'),categoryMetric=ref<'gross'|'net'>('gross')
const show=computed(()=>settings.showAmount),accounts=computed(()=>data.value?.accounts.filter(a=>a.currency===filters.currency)||[]),years=computed(()=>[...new Set([year.value,...Object.keys(data.value?.years||{})])].sort().reverse())
const queues=[{key:'category',name:'分类待核对'},{key:'refund',name:'退款待确认'},{key:'receipt',name:'凭证待匹配'},{key:'pending',name:'每日摘要待确认'}]
const planTabs=[{key:'schedule',name:'还款安排'},{key:'statement',name:'月度账单'},{key:'reference',name:'其他参考'}]
const filtersExpanded=ref(false),activeFilterCount=computed(()=>[filters.from,filters.to,filters.bank,filters.account,filters.confirmation,filters.category,filters.channel,filters.kind==='ledger'?'':filters.kind].filter(Boolean).length)
const linkFilters=computed(()=>({currency:filters.currency,from:filters.from,to:filters.to,bank:filters.bank,account:filters.account,confirmation:filters.confirmation}))
const money=(v:number)=>amount(v,filters.currency,show.value)
const projection=ref<{starting:number|null;unknownAmounts:number;points:{date:string;billed:number;estimated:number;remaining:number|null}[]}|null>(null)
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';selected.value=[];try{const r=await getWorkspace({...filters,offset:offset.value,year:mode.value==='reports'&&period.value==='year'?year.value:''});if(seq===sequence){data.value=r;if(mode.value==='plans'){const p=await get<typeof projection.value>('/workspace/projection?currency='+filters.currency);if(seq===sequence)projection.value=p}}}catch(e){if(seq===sequence)error.value=e instanceof Error?e.message:String(e)}finally{if(seq===sequence)loading.value=false}}
function refresh(){offset.value=0;load()}
function setPeriod(){if(period.value==='year'){filters.from=year.value+'-01-01';filters.to=year.value+'-12-31'}else{filters.from=month.value+'-01';const [y,m]=month.value.split('-').map(Number);filters.to=localDate(new Date(y,m,0))}refresh()}
function reset(){Object.assign(filters,{from:'',to:'',bank:'',account:'',category:'',confirmation:'',q:'',channel:''});if(mode.value==='reports')setPeriod();else refresh()}
function selectQueue(q:string){filters.queue=q;filters.kind='';refresh()}
function openCategory(category:string){router.push({path:'/detail',query:{...linkFilters.value,category}})}
function openPeriod(date:string){let from=date,to=date;if(date.length===7){from=date+'-01';const [y,m]=date.split('-').map(Number);to=localDate(new Date(y,m,0))}router.push({path:'/detail',query:{...linkFilters.value,from,to}})}
async function bulkSave(){if(!data.value)return;saving.value=true;try{await saveEdits(data.value.items.filter(x=>selected.value.includes(x.key)).map(x=>({key:x.key,version:x.version,edit:{...x.edit,category:bulkCategory.value,reviewed:true}})),'人工批量分类');await load()}catch(e){error.value=String(e)}finally{saving.value=false}}
watch(()=>route.fullPath,()=>{data.value=null;recordKey.value='';Object.assign(filters,{from:'',to:'',bank:'',account:'',category:'',confirmation:'',q:'',queue:'',channel:'',kind:mode.value==='plans'?'schedule':mode.value==='review'?'':'ledger'});for(const k of Object.keys(filters) as (keyof typeof filters)[]){if(typeof route.query[k]==='string')filters[k]=route.query[k] as string}if(mode.value==='review')filters.queue=String(route.query.queue||'category');if(mode.value==='home'){filters.from=localDate().slice(0,7)+'-01';filters.to=localDate()}if(mode.value==='reports')setPeriod();else refresh()},{immediate:true})
onBeforeUnmount(()=>{sequence++})
</script>
